{
	"name": "opencode-mnemon",
	"version": "0.3.2",
	"type": "module",
	"description": "OpenCode plugin: project-scoped automatic memory via mnemon CLI (runtime capture, rule + LLM extraction, recall/status injection)",
	"license": "MIT",
	"repository": {
		"type": "git",
		"url": "git+ssh://git@github.com/CR903/opencode-mnemon.git"
	},
	"bugs": {
		"url": "https://github.com/CR903/opencode-mnemon/issues"
	},
	"homepage": "https://github.com/CR903/opencode-mnemon#readme",
	"keywords": [
		"opencode",
		"opencode-plugin",
		"plugin",
		"mnemon",
		"memory",
		"recall"
	],
	"main": "./mnemon.js",
	"bin": {
		"opencode-mnemon": "./bin/init.mjs",
		"opencode-mnemon-init": "./bin/init.mjs"
	},
	"exports": {
		".": "./mnemon.js"
	},
	"files": [
		"mnemon.js",
		"bin/",
		"README.md",
		"README.zh-CN.md",
		"LICENSE"
	],
	"engines": {
		"node": ">=18"
	},
	"scripts": {
		"sync:docs": "node scripts/sync-docs.mjs",
		"sync:docs:check": "node scripts/sync-docs.mjs --check",
		"test:build": "sh tests/build-mnemon-test.sh",
		"test": "sh tests/build-mnemon-test.sh && node scripts/sync-docs.mjs --check && node tests/mnemon-recall-gate-test.mjs && node tests/mnemon-extract-test.mjs && node tests/mnemon-remember-e2e.mjs && node tests/mnemon-llm-extract-test.mjs && node tests/mnemon-init-test.mjs",
		"test:deploy": "sh tests/build-mnemon-test.sh \"$PWD/mnemon.js\" && node scripts/sync-docs.mjs --check && node tests/mnemon-recall-gate-test.mjs && node tests/mnemon-extract-test.mjs && node tests/mnemon-remember-e2e.mjs && node tests/mnemon-llm-extract-test.mjs && node tests/mnemon-init-test.mjs",
		"deploy": "node scripts/deploy.mjs",
		"deploy:check": "node scripts/deploy.mjs --check",
		"version:patch": "npm version patch",
		"version:minor": "npm version minor",
		"version:major": "npm version major"
	},
	"peerDependencies": {
		"@opencode/plugin": ">=2.0.0"
	},
	"peerDependenciesMeta": {
		"@opencode/plugin": {
			"optional": true
		}
	},
	"publishConfig": {
		"access": "public",
		"registry": "https://registry.npmjs.org/"
	}
}
